// QA hardening script (not a committed test). Run with node from the app dir so playwright resolves.
const { chromium } = require(process.cwd() + '/node_modules/@playwright/test');
const AxeBuilder = require(process.cwd() + '/node_modules/@axe-core/playwright').default;
const URL = 'http://127.0.0.1:4173/';
const results = [];
const rec = (id, ok, ev) => { results.push({ id, ok, ev }); console.log(`${ok ? 'PASS' : 'FAIL'} ${id} :: ${ev}`); };

(async () => {
  const browser = await chromium.launch();
  const consoleMsgs = [];
  const newPage = async (opts = {}) => {
    const ctx = await browser.newContext(opts);
    const p = await ctx.newPage();
    p.on('console', (m) => { if (['error', 'warning'].includes(m.type())) consoleMsgs.push(`${m.type()}: ${m.text()}`); });
    p.on('pageerror', (e) => consoleMsgs.push('pageerror: ' + e.message));
    p.on('requestfailed', (r) => consoleMsgs.push('requestfailed: ' + r.url()));
    return p;
  };
  const E = '#marks-earned', T = '#total-marks', P = '#pass-mark';

  // 1. Title, favicon
  let page = await newPage({ viewport: { width: 1280, height: 800 } });
  const favResp = [];
  page.on('response', (r) => { if (r.url().includes('favicon')) favResp.push(`${r.status()} ${r.headers()['content-type']}`); });
  await page.goto(URL);
  const ids = await page.$$eval('input', (els) => els.map((e) => e.id));
  rec('ids', ids.length === 3, JSON.stringify(ids));
  const [e, t, p] = ids.map((i) => '#' + i);
  rec('title=M-30', (await page.title()) === 'Quiz score and pass-mark calculator', JSON.stringify(await page.title()));
  const fav = await page.request.get(URL + 'favicon.svg');
  const favHref = await page.getAttribute('link[rel=icon]', 'href');
  rec('favicon', fav.status() === 200 && (await fav.text()).includes('<svg'), `link href=${favHref}; GET favicon.svg ${fav.status()} ${fav.headers()['content-type']}; page-load responses: ${favResp.join(',') || 'none observed'}`);

  // 2. Keyboard-only: Tab from body
  await page.keyboard.press('Tab');
  const order = [];
  for (let i = 0; i < 5; i++) {
    order.push(await page.evaluate(() => document.activeElement && (document.activeElement.id || document.activeElement.tagName)));
    await page.keyboard.press('Tab');
  }
  rec('tab order', order.slice(0, 3).join('>') === [e, t, p].map((s) => s.slice(1)).join('>'), 'Tab sequence: ' + order.join(' > '));
  // Shift+Tab back from pass mark
  await page.focus(p); await page.keyboard.press('Shift+Tab');
  const back = await page.evaluate(() => document.activeElement.id);
  rec('shift-tab / no trap', back === e.slice(1) || back === t.slice(1), 'Shift+Tab from pass mark -> ' + back + '; Tab past pass mark leaves card -> ' + order[3]);
  // focus ring
  await page.focus(e);
  const ring = await page.$eval(e, (el) => { const s = getComputedStyle(el); return `${s.outlineStyle} ${s.outlineWidth} ${s.outlineColor} offset ${s.outlineOffset}`; });
  rec('focus ring visible', /solid/.test(ring) && !ring.startsWith('none') && !/ 0px /.test(ring), ring);
  const btns = await page.locator('button').count();
  const kbd = await page.locator('kbd').count();
  const body = await page.locator('body').innerText();
  rec('no Next learner / Esc hint', btns === 0 && kbd === 0 && !body.includes('Next learner') && !body.includes('or press Esc'), `buttons=${btns} kbd=${kbd}`);
  // Esc does nothing harmful
  await page.fill(e, '17.5'); await page.fill(t, '23'); await page.focus(e); await page.keyboard.press('Escape');
  rec('Esc no-op', (await page.inputValue(e)) === '17.5', 'earned after Esc=' + (await page.inputValue(e)));

  // 3. Screen reader basics
  const labels = await page.$$eval('input', (els) => els.map((el) => {
    const l = document.querySelector(`label[for="${el.id}"]`);
    return `${el.id}: label="${l ? l.textContent : ''}" inputmode=${el.getAttribute('inputmode')} describedby=${el.getAttribute('aria-describedby')}`;
  }));
  rec('labels', labels.every((s) => /label="[^"]+"/.test(s)), labels.join(' | '));
  const accName = await page.getByLabel('Pass mark (percent)', { exact: true }).count();
  rec('pass mark accessible name incl. M-37', accName === 1, 'getByLabel("Pass mark (percent)") count=' + accName);
  await page.reload();
  await page.fill(e, '17.5'); await page.fill(t, '23');
  const st0 = await page.textContent('[role=status]');
  await page.waitForTimeout(650);
  const st1 = await page.textContent('[role=status]');
  rec('aria-live after 500ms', (st0 || '') === '' && /76\.0/.test(st1) && /Pass/.test(st1), `at 0 ms: "${st0}"; at 650 ms: "${st1}"; live=${await page.getAttribute('[role=status]', 'aria-live')} atomic=${await page.getAttribute('[role=status]', 'aria-atomic')}`);
  await page.fill(e, '23.5');
  await page.waitForTimeout(650);
  const inv = await page.getAttribute(e, 'aria-invalid');
  const dby = await page.getAttribute(e, 'aria-describedby');
  const errText = await page.textContent('#' + dby);
  const stErr = await page.textContent('[role=status]');
  rec('aria-invalid + describedby', inv === 'true' && /can't be more than the total/.test(errText), `aria-invalid=${inv}; #${dby}="${errText.trim()}"; status="${stErr}"`);
  await page.fill(e, '17.5');
  rec('aria-invalid removed on fix', (await page.getAttribute(e, 'aria-invalid')) === null, 'aria-invalid after fix=' + (await page.getAttribute(e, 'aria-invalid')));

  // 4. Reduced motion
  const rm = await newPage({ reducedMotion: 'reduce' });
  await rm.goto(URL);
  const tr = await rm.$$eval('*', (els) => [...new Set(els.map((x) => getComputedStyle(x).transitionDuration + '/' + getComputedStyle(x).animationDuration))]);
  rec('reduced motion', tr.every((s) => s.split('/').every((d) => d.split(',').every((v) => parseFloat(v) === 0))), 'distinct transition/animation durations: ' + tr.join(' ; '));
  const nm = await newPage();
  await nm.goto(URL);
  const trN = await nm.$eval(e, (x) => getComputedStyle(x).transitionDuration);
  rec('motion on by default (control)', true, 'input transition-duration without reduce: ' + trN);

  // 5. Contrast via axe, light + dark, phone + wide
  for (const cs of ['light', 'dark']) for (const w of [320, 1280]) {
    const ap = await newPage({ colorScheme: cs, viewport: { width: w, height: 800 } });
    await ap.goto(URL);
    await ap.fill(e, 'abc'); await ap.fill(t, '23');
    const a1 = await new AxeBuilder({ page: ap }).withTags(['wcag2a', 'wcag2aa', 'wcag21aa', 'wcag22aa']).analyze();
    await ap.fill(e, '12');
    const a2 = await new AxeBuilder({ page: ap }).withRules(['color-contrast']).analyze();
    const v = [...a1.violations, ...a2.violations].map((x) => x.id);
    rec(`axe ${cs} ${w}px`, v.length === 0, `violations=${JSON.stringify(v)}; color-contrast passes nodes=${(a2.passes.find((x) => x.id === 'color-contrast') || { nodes: [] }).nodes.length}`);
  }

  // 6. 320 px no horizontal scroll in every state incl. long input
  const sp = await newPage({ viewport: { width: 320, height: 640 }, isMobile: true, hasTouch: true });
  await sp.goto(URL);
  const sw = [];
  for (const [a, b, c] of [['', '', '70'], ['17.5', '23', '70'], ['abc', '0', '70.05'], ['9'.repeat(400), '1000000', '70'], ['999999.99', '1000000', '0']]) {
    await sp.fill(e, a); await sp.fill(t, b); await sp.fill(p, c);
    sw.push(await sp.evaluate(() => `${document.documentElement.scrollWidth}/${document.documentElement.clientWidth}`));
  }
  rec('320px no h-scroll', sw.every((s) => { const [x, y] = s.split('/').map(Number); return x <= y; }), 'scrollWidth/clientWidth per state: ' + sw.join(', '));

  // 7. Rapid input
  const rp = await newPage();
  await rp.goto(URL);
  await rp.click(t); await rp.keyboard.type('23', { delay: 0 });
  await rp.click(e);
  for (let i = 0; i < 30; i++) { await rp.keyboard.type('17.5', { delay: 0 }); for (let j = 0; j < 4; j++) await rp.keyboard.press('Backspace'); }
  await rp.keyboard.type('17.5', { delay: 0 });
  const rText = await rp.locator('.result').innerText();
  await rp.waitForTimeout(650);
  const rSt = await rp.textContent('[role=status]');
  rec('rapid input', /76\.0%/.test(rText) && /Pass/.test(rText) && !/NaN|Infinity|undefined/.test(rText), `after 30 type/delete cycles: result="${rText.replace(/\s+/g, ' ')}"; status="${rSt}"`);

  // 8. Reload
  await rp.fill(p, '65');
  await rp.reload();
  const vals = [await rp.inputValue(e), await rp.inputValue(t), await rp.inputValue(p)];
  const rl = (await rp.locator('.result').innerText()).replace(/\s+/g, ' ');
  rec('reload', vals.join('|') === '||70' && rl.includes('Enter marks earned and total marks possible to see the score.'), `values=${JSON.stringify(vals)}; result="${rl}"`);

  // 9. Card height constant across states (headroom check in Chromium)
  for (const w of [375, 1280]) {
    const hp = await newPage({ viewport: { width: w, height: 900 } });
    await hp.goto(URL);
    const hs = [];
    const states = [['', '', '70'], ['17.5', '23', '70'], ['15.5', '23', '70'], ['17.5', '23', ''], ['abc', '0', '70'], ['abc', '-5', '100.1'], ['16.08', '23', '69.9'], ['0.01', '1000000', '70']];
    for (const [a, b, c] of states) {
      await hp.fill(e, a); await hp.fill(t, b); await hp.fill(p, c);
      hs.push(await hp.evaluate(() => { const r = document.querySelector('.result'); const cs = getComputedStyle(r); const inner = [...r.children].reduce((s, ch) => s + ch.getBoundingClientRect().height, 0); return `${document.querySelector('.card').getBoundingClientRect().bottom.toFixed(2)}(content ${(r.scrollHeight).toFixed(0)}/min ${cs.minHeight})`; }));
    }
    const bottoms = new Set(hs.map((s) => s.split('(')[0]));
    rec(`card bottom stable ${w}px`, bottoms.size === 1, hs.join(', '));
  }

  rec('console clean', consoleMsgs.length === 0, consoleMsgs.length ? consoleMsgs.join(' | ') : 'no console errors/warnings/page errors/failed requests');
  await browser.close();
  const fails = results.filter((r) => !r.ok).length;
  console.log(`\nTOTAL ${results.length} checks, ${fails} failed`);
})().catch((err) => { console.error(err); process.exit(1); });

